console.log(import.meta.env.MODE, import.meta.env.PROD, import.meta.env.DEV);
```

### 四、Vite 特有能力

```ts
// 1. 批量导入（编译期展开为静态 import）
const modules = import.meta.glob('./pages/*.tsx');           // 懒加载，值是 () => Promise
const eager = import.meta.glob('./locales/*.json', { eager: true }); // 立即加载

// 2. 静态资源
import logoUrl from './logo.png';        // 得到 URL 字符串
import rawText from './readme.md?raw';   // 原始文本
import workerCtor from './my.worker?worker';

// 3. HMR API
if (import.meta.hot) {
  import.meta.hot.accept('./store.ts', (mod) => {
    console.log('模块已热更新', mod);
  });
}
```

### 实践任务

1. `pnpm create vite` 建一个 React + TS 项目，删除 `node_modules/.vite` 后重启，观察依赖预构建日志。
2. 配置 `server.proxy` 联调本地后端，解决跨域。
3. 用 `rollup-plugin-visualizer` 分析产物，调整 `manualChunks` 把 vendor 拆开。

### 🛑 易错点

1. **以为开发环境表现等于生产环境**：dev 用 esbuild 且不打包，prod 用 Rollup 且做 tree-shaking，两者在「CJS 互操作、动态导入路径、环境变量替换」上行为可能不同。上线前必须跑 `vite build && vite preview` 验证。
2. **esbuild 不做类型检查**：Vite 转译 TS 时只是**擦除类型**，类型错误不会阻断构建。必须在 `build` 脚本里加 `tsc --noEmit`，并接入 CI。
3. **环境变量忘记 `VITE_` 前缀**：只有 `VITE_` 开头的变量会被注入客户端，其他变量在浏览器里是 `undefined`。反过来，**不要把密钥写进 `VITE_` 变量**，它会被明文打进产物。
4. **在 `manualChunks` 里过度拆包**：拆得太碎会产生大量小请求与重复依赖，HTTP/1.1 下反而更慢。优先只拆变更频率低的大型第三方库。

### ✅ 自测题

1. **问**：为什么 Vite 开发环境不打包也能跑？
   **答**：现代浏览器原生支持 ESM，浏览器会按 `import` 语句逐个请求模块；Vite 只需拦截请求做按需转译，把「打包」这一最耗时的步骤推迟到生产构建。

2. **问**：依赖预构建解决了哪两个问题？
   **答**：① 把 CJS/UMD 依赖转换成浏览器可用的 ESM；② 将含大量内部模块的包合并成单个请求，避免浏览器请求瀑布导致的加载缓慢。

3. **问**：Vite 生产为什么用 Rollup 而不是 esbuild？
   **答**：esbuild 快但在代码分割、CSS 处理、tree-shaking 精度与插件生态上不如 Rollup 成熟。Vite 因此选择「dev 用 esbuild 求快，build 用 Rollup 求稳」。

4. **问**：`import.meta.glob` 与运行时 `import()` 有何不同？
   **答**：`import.meta.glob` 是 Vite 的**编译期**特性，构建时会被展开为一组静态 import，因此路径必须是字面量；运行时 `import()` 的路径可以是变量，但打包器难以静态分析。

## 核心知识点

### 一、五个核心概念

```js
// webpack.config.js
const path = require('node:path');
const HtmlWebpackPlugin = require('html-webpack-plugin');
const MiniCssExtractPlugin = require('mini-css-extract-plugin');

module.exports = {
  mode: 'production',                    // development | production | none

  entry: { main: './src/index.js' },     // 1. 入口：依赖图的起点

  output: {                              // 2. 出口
    path: path.resolve(__dirname, 'dist'),
    filename: '[name].[contenthash:8].js',
    chunkFilename: 'chunks/[name].[contenthash:8].js',
    assetModuleFilename: 'assets/[hash][ext][query]',
    clean: true,                         // 构建前清空 dist（webpack 5）
    publicPath: '/',
  },

  module: {
    rules: [                             // 3. loader：把非 JS 转成模块
      { test: /\.tsx?$/, exclude: /node_modules/, use: 'babel-loader' },
      {
        test: /\.s?css$/,
        // 注意：数组从右往左（从下往上）执行
        use: [MiniCssExtractPlugin.loader, 'css-loader', 'postcss-loader', 'sass-loader'],
      },
      { test: /\.(png|jpe?g|svg|woff2?)$/, type: 'asset' }, // webpack5 资源模块
    ],
  },

  plugins: [                             // 4. plugin：介入构建生命周期
    new HtmlWebpackPlugin({ template: './public/index.html' }),
    new MiniCssExtractPlugin({ filename: '[name].[contenthash:8].css' }),
  ],

  resolve: {
    extensions: ['.tsx', '.ts', '.js'],
    alias: { '@': path.resolve(__dirname, 'src') },
  },
};
```

**loader vs plugin**：loader 是**文件转换器**（单个文件级别，链式调用）；plugin 基于 **Tapable 钩子**介入整个编译生命周期，能力更强（生成 HTML、抽取 CSS、注入变量、分析产物）。

### 二、代码分割（Code Splitting）

```js
module.exports = {
  optimization: {
    // 把运行时代码单独抽出，避免它变化导致所有 chunk 的 hash 失效
    runtimeChunk: 'single',
    splitChunks: {
      chunks: 'all',
      cacheGroups: {
        vendor: {
          test: /[\\/]node_modules[\\/]/,
          name: 'vendors',
          priority: 10,
        },
        common: {
          minChunks: 2,       // 被引用两次以上才抽取
          name: 'common',
          reuseExistingChunk: true,
        },
      },
    },
  },
};
```

```js
// 动态 import：天然的分割点，配合魔法注释命名
const Chart = () => import(/* webpackChunkName: "chart" */ './Chart.js');

// 预取：空闲时下载（生成 <link rel="prefetch">）
import(/* webpackPrefetch: true */ './Modal.js');
```

### 三、开发服务器与 HMR

```js
module.exports = {
  devtool: 'eval-cheap-module-source-map', // 开发用，构建快
  devServer: {
    port: 8080,
    hot: true,
    historyApiFallback: true,   // SPA 路由刷新 404 的解法
    proxy: [{ context: ['/api'], target: 'http://localhost:3000', changeOrigin: true }],
  },
  cache: { type: 'filesystem' }, // webpack5 持久化缓存，二次构建大幅提速
};
```

### 四、构建产物优化清单

- `[contenthash]` 文件名 + 长缓存。
- `splitChunks` 分离 vendor 与公共模块。
- `mode: 'production'` 自动开启 `TerserPlugin` 压缩与 `usedExports` 标记。
- `sideEffects: false` 让未使用模块被彻底剔除。
- `webpack-bundle-analyzer` 可视化定位体积大户。

### 实践任务

1. 从零写一个最小 webpack 配置，跑通 TS + CSS + 图片。
2. 用 `webpack-bundle-analyzer` 分析产物，把 `node_modules` 拆成独立 vendor chunk。
3. 打开 `cache: { type: 'filesystem' }`，对比首次与二次构建耗时。

### 🛑 易错点

1. **搞反 loader 执行顺序**：`use` 数组从**右到左（下到上）**执行。写成 `['sass-loader', 'css-loader', 'style-loader']` 会先把 CSS 当 Sass 之外的东西处理，直接报错。
2. **生产环境用了开发用的 `devtool`**：`eval` 系列会把源码内联进产物，体积暴涨且泄露源码。生产应使用 `source-map`（独立文件、不部署）或 `hidden-source-map`。
3. **用 `[hash]` 而非 `[contenthash]`**：`[hash]` 是整次构建的 hash，任意文件改动都会让所有产物文件名变化，缓存全部失效。应使用与文件内容绑定的 `[contenthash]`。
4. **`babel-loader` 没有排除 `node_modules`**：对整个依赖目录做转译会让构建慢数倍。要加 `exclude: /node_modules/`，并善用 `cacheDirectory: true`。

### ✅ 自测题

1. **问**：loader 与 plugin 的本质区别是什么？
   **答**：loader 工作在**模块加载阶段**，负责把某类文件转换成 webpack 能理解的 JS 模块，是纯函数式的链式转换；plugin 通过 Tapable 订阅 compiler/compilation 的**生命周期钩子**，可以在打包全过程中做任意事情。

2. **问**：`splitChunks.chunks: 'all'` 意味着什么？
   **答**：对同步引入和异步引入的模块都参与分割。默认值 `'async'` 只处理动态导入的模块，改成 `'all'` 才能把同步引入的第三方库也抽成公共 chunk。

3. **问**：为什么要配置 `runtimeChunk: 'single'`？
   **答**：webpack 的运行时代码包含模块映射表，每次新增 chunk 都会变化。把它单独抽出后，业务 chunk 的 contenthash 不会因映射表变动而失效，长缓存命中率更高。

4. **问**：Webpack 与 Vite 该如何选型？
   **答**：新项目、纯前端应用优先 Vite（启动与 HMR 体验碾压）；需要复杂自定义构建流程、依赖大量既有 webpack 插件、或要支持很老的浏览器与微前端方案时，Webpack 生态更成熟稳妥。

## 核心知识点

### 一、JSX 到底是什么

JSX 是语法糖，编译后变成函数调用。React 17 起默认使用 **automatic runtime**，不再需要在每个文件手动 `import React`。

```jsx
// 你写的
const el = <h1 className="title">Hello {name}</h1>;

// 编译后（automatic runtime）
import { jsx as _jsx } from 'react/jsx-runtime';
const el = _jsx('h1', { className: 'title', children: ['Hello ', name] });
```

得到的是一个描述 UI 的**普通对象**（React Element），不是真实 DOM。

### 二、JSX 语法要点

```jsx
function Profile({ user, items, isVip }) {
  return (
    <div className="card" style={{ padding: 16, fontSize: 14 }}>
      {/* 表达式插值：只能放表达式，不能放 if/for 语句 */}
      <h2>{user.name.toUpperCase()}</h2>

      {/* 条件渲染 */}
      {isVip ? <span>VIP</span> : null}
      {items.length > 0 && <p>共 {items.length} 项</p>}

      {/* 列表渲染：key 必须稳定且唯一 */}
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.title}</li>
        ))}
      </ul>

      {/* label 用 htmlFor，不是 for */}
      <label htmlFor="q">搜索</label>
      <input id="q" defaultValue="" />
    </div>
  );
}
```

- 属性名用 **camelCase**：`className`、`htmlFor`、`onClick`、`tabIndex`。
- 必须有**单一根元素**，可用 `<>...</>`（Fragment）避免多余 DOM。
- 组件名**必须大写开头**，小写会被当成原生 HTML 标签。

### 三、函数组件 vs 类组件

```jsx
// 函数组件（现代标准）
function Welcome({ name }) {
  return <h1>你好，{name}</h1>;
}

// 类组件（老代码里仍会遇到）
class WelcomeClass extends React.Component {
  render() {
    return <h1>你好，{this.props.name}</h1>;
  }
}
```

函数组件配合 Hooks 已能覆盖全部能力，新代码一律使用函数组件。类组件目前唯一不可替代的场景是 **错误边界**（`componentDidCatch` / `getDerivedStateFromError`），实际项目通常直接用 `react-error-boundary` 库。

### 四、组合优于继承

React 官方明确不推荐用继承复用 UI，应使用 **children 与 props 插槽**。

```jsx
// 通用容器：通过 children 接收任意内容
function Card({ title, extra, children }) {
  return (
    <section className="card">
      <header>
        <h3>{title}</h3>
        {extra}
      </header>
      <div className="card-body">{children}</div>
    </section>
  );
}

// 使用：把差异部分作为“插槽”传入
<Card title="用户信息" extra={<button>编辑</button>}>
  <p>邮箱：ada@example.com</p>
</Card>;
```

### 实践任务

1. 用 `pnpm create vite my-app --template react-ts` 建项目，写一个 `Card` 组件并支持 `title`/`extra`/`children` 三个插槽。
2. 在浏览器里 `console.log(<div />)`，观察 React Element 对象结构。
3. 把一个类组件改写为函数组件，对比代码量。

### 🛑 易错点

1. **组件名首字母小写**：`<myButton />` 会被编译成 `_jsx('myButton')`，React 当作未知 HTML 标签处理，页面什么都不渲染且无明显报错。
2. **用 `&&` 渲染数字**：`{count && <List />}` 在 `count === 0` 时会渲染出字符串 `0` 而不是什么都不渲染（`0` 是假值但仍是合法 ReactNode）。应写 `{count > 0 && <List />}`。
3. **在 JSX 里写语句**：`{if (a) {...}}` 是语法错误，JSX 花括号内只能是**表达式**。用三元、`&&` 或把逻辑提到 return 之前。
4. **用数组索引当 key**：列表发生插入、删除、排序时，索引与内容的对应关系错位，会导致状态串位（比如输入框内容跑到了别的行）。应使用数据本身的稳定 id。

### ✅ 自测题

1. **问**：JSX 编译后是什么？
   **答**：是 `jsx()`（或旧版 `React.createElement()`）的调用，返回描述 UI 的普通 JavaScript 对象（React Element），包含 type、props、key 等字段，React 再据此更新真实 DOM。

2. **问**：为什么 React 17 之后可以不写 `import React from 'react'`？
   **答**：新的 automatic JSX transform 会自动从 `react/jsx-runtime` 引入 `jsx` 函数，不再依赖作用域中存在 `React` 变量。但如果代码里直接用到 `React.xxx` API，仍需导入。

3. **问**：为什么 React 提倡组合而非继承？
   **答**：UI 复用的诉求通常是「内容替换」而不是「行为继承」。用 `children`、插槽 props 与自定义 Hook 组合，比继承层级更浅、依赖更明确、也更容易测试与重构。

4. **问**：Fragment 解决了什么问题？
   **答**：组件必须返回单一根节点，Fragment（`<>...</>`）允许返回多个兄弟元素而不额外生成 DOM 节点，避免破坏 flex/grid 布局与 CSS 选择器结构。

## 核心知识点

### 一、Props 是只读的

组件对 props 必须像纯函数一样对待：**只读不改**。要改变数据，必须由拥有该 state 的父组件通过回调更新。

```tsx
interface ButtonProps {
  label: string;
  variant?: 'primary' | 'ghost';   // 可选 + 字面量联合
  disabled?: boolean;
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
  children?: React.ReactNode;
}

function Button({ label, variant = 'primary', disabled = false, onClick, children }: ButtonProps) {
  return (
    <button className={`btn btn-${variant}`} disabled={disabled} onClick={onClick}>
      {label}
      {children}
    </button>
  );
}
```

**解构时写默认值**是函数组件设置默认 props 的标准做法（类组件的 `defaultProps` 在函数组件上已被废弃）。

### 二、children 与插槽模式

```tsx
type ModalProps = {
  open: boolean;
  title: React.ReactNode;
  footer?: React.ReactNode;     // 插槽：允许传入任意 JSX
  onClose: () => void;
  children: React.ReactNode;
};

function Modal({ open, title, footer, onClose, children }: ModalProps) {
  if (!open) return null;
  return (
    <div className="mask" onClick={onClose}>
      <div className="dialog" onClick={(e) => e.stopPropagation()}>
        <header>{title}</header>
        <main>{children}</main>
        <footer>{footer ?? <button onClick={onClose}>关闭</button>}</footer>
      </div>
    </div>
  );
}
```

### 三、透传剩余属性

```tsx
type InputProps = React.ComponentPropsWithoutRef<'input'> & { error?: string };

function Input({ error, className = '', ...rest }: InputProps) {
  return (
    <div>
      {/* 把 placeholder、type、aria-* 等原生属性一次性透传 */}
      <input {...rest} className={`input ${error ? 'has-error' : ''} ${className}`} />
      {error && <span role="alert">{error}</span>}
    </div>
  );
}
```

`React.ComponentPropsWithoutRef<'input'>` 能自动拿到全部原生 input 属性类型，比手写枚举可靠得多。

### 四、把函数当 props：状态提升

```tsx
function SearchBox({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  return <input value={value} onChange={(e) => onChange(e.target.value)} />;
}

function Page() {
  const [keyword, setKeyword] = useState('');
  return (
    <>
      <SearchBox value={keyword} onChange={setKeyword} />
      <p>你在搜：{keyword}</p>
    </>
  );
}
```

这就是**受控组件**：值由父级 state 掌控，子组件只负责展示与上报，实现单向数据流。

### 实践任务

1. 写一个 `Input` 组件，透传全部原生属性并支持 `error` 提示。
2. 实现 `Modal`，用 `footer` 插槽让调用方自定义按钮区域。
3. 把两个兄弟组件之间的共享状态提升到父组件，体会单向数据流。

### 🛑 易错点

1. **直接修改 props**：`props.list.push(x)` 或 `props.user.name = 'x'` 不会触发重渲染，还会污染父组件数据源，属于最难排查的 bug 之一。必须回调父组件用新对象替换。
2. **在 JSX 里创建新对象/数组字面量**：`<Child style={{ a: 1 }} list={[]} />` 每次渲染都生成新引用，会让 `React.memo` 完全失效。需要时用 `useMemo` 缓存，或把常量提到组件外部。
3. **仍在函数组件上用 `defaultProps`**：React 18.3 起会给出弃用警告，React 19 已移除对函数组件 `defaultProps` 的支持。请改用参数解构默认值。
4. **依赖 PropTypes 做类型校验**：React 19 已移除 `propTypes` 的运行时检查（会被忽略）。类型校验应交给 TypeScript。

### ✅ 自测题

1. **问**：为什么说 React 是单向数据流？
   **答**：数据只能从父组件通过 props 流向子组件；子组件想改变数据必须调用父组件传下来的回调，由拥有 state 的一方更新。这让数据变更路径唯一且可追踪。

2. **问**：函数组件如何设置默认 props？
   **答**：在参数解构时写默认值，如 `function C({ size = 'md' })`。`defaultProps` 在函数组件上已被废弃并在 React 19 中移除。

3. **问**：`React.ReactNode` 与 `JSX.Element` 有什么区别？
   **答**：`JSX.Element` 只表示单个 JSX 元素；`ReactNode` 涵盖元素、字符串、数字、数组、`null`、`undefined`、布尔值等一切可渲染内容，因此 `children` 类型应使用 `ReactNode`。

4. **问**：什么是受控组件？
   **答**：表单元素的值由 React state 提供（`value` + `onChange`），React 是唯一数据源。与之相对的是非受控组件，值由 DOM 自身维护，通过 `defaultValue` 初始化并用 ref 读取。

## 核心知识点

### 一、useState

```jsx
import { useState } from 'react';

function Counter() {
  const [count, setCount] = useState(0);
  // 惰性初始化：函数只在首次渲染时执行一次，适合昂贵计算
  const [list, setList] = useState(() => JSON.parse(localStorage.getItem('list') ?? '[]'));

  function handleTriple() {
    // ❌ 三次都基于同一个旧 count，只加 1
    // setCount(count + 1); setCount(count + 1); setCount(count + 1);

    // ✅ 函数式更新：基于最新值排队计算
    setCount((c) => c + 1);
    setCount((c) => c + 1);
    setCount((c) => c + 1);
  }

  return (
    <>
      <p>{count}</p>
      <button onClick={handleTriple}>+3</button>
      <button onClick={() => setList((prev) => [...prev, Date.now()])}>追加</button>
    </>
  );
}
```

要点：

- **state 是快照**：一次渲染中 `count` 的值是固定的，`setCount` 不会立刻改变当前作用域里的变量。
- **批处理**：React 18 起在所有场景（包括 `setTimeout`、原生事件、Promise 回调）都会自动批量合并更新。
- **必须不可变更新**：数组用 `[...prev, x]`、`prev.filter()`、`prev.map()`；对象用 `{ ...prev, key: v }`。直接 `push`/赋值不会触发渲染。

### 二、useEffect

`useEffect` 的定位是「**与外部系统同步**」：订阅、计时器、手动 DOM 操作、网络请求。

```jsx
import { useState, useEffect } from 'react';

function UserPanel({ userId }) {
  const [user, setUser] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();

    (async () => {
      try {
        const res = await fetch(`/api/users/${userId}`, { signal: controller.signal });
        setUser(await res.json());
      } catch (e) {
        if (e.name !== 'AbortError') setError(e);
      }
    })();

    // 清理函数：依赖变化或卸载时执行，避免竞态与内存泄漏
    return () => controller.abort();
  }, [userId]); // 依赖数组：userId 变化才重新执行

  if (error) return <p>加载失败</p>;
  return <p>{user?.name ?? '加载中'}</p>;
}
```

依赖数组三种形态：

- `useEffect(fn)`：每次渲染后都执行。
- `useEffect(fn, [])`：只在挂载后执行一次（严格模式开发环境会执行两次）。
- `useEffect(fn, [a, b])`：`a` 或 `b` 变化时执行（用 `Object.is` 比较）。

### 三、不该用 useEffect 的场景

```jsx
// ❌ 用 effect 派生 state：多一次渲染，还容易不同步
const [full, setFull] = useState('');
useEffect(() => setFull(`${first} ${last}`), [first, last]);

// ✅ 渲染期直接算
const full = `${first} ${last}`;

// ✅ 计算昂贵时用 useMemo
const sorted = useMemo(() => bigList.slice().sort(cmp), [bigList]);
```

**能在渲染期算出来的，不要放进 effect。** 用户事件触发的逻辑应写在事件处理函数里，而不是 effect。

### 实践任务

1. 写一个每秒自增的计时器，用 `setInterval` + 清理函数，验证卸载后不再报警告。
2. 实现一个搜索框，快速切换关键词时用 `AbortController` 取消旧请求，观察竞态。
3. 找出项目中「用 effect 同步派生 state」的代码，改为渲染期计算。

### 🛑 易错点

1. **在事件里连续多次 `setX(x + 1)`**：每次读的都是本次渲染的旧快照，最终只生效一次。需要基于前值时一律用函数式更新 `setX(prev => ...)`。
2. **依赖数组撒谎**：为了「只执行一次」而写空数组，但 effect 内部用了会变化的变量，就会读到过期闭包值。正确做法是补全依赖，或用 `useEffect` 之外的方案（事件处理、`useRef`）。
3. **忘记清理副作用**：定时器、事件监听、WebSocket、订阅未在返回函数中清理，会导致内存泄漏和「组件已卸载仍 setState」的问题。
4. **对 StrictMode 下 effect 执行两次感到困惑**：这是开发环境刻意的行为，用于暴露「没有清理逻辑」的副作用。生产构建只执行一次。不要用 `useRef` 标志位去绕过它，应该把清理写对。

### ✅ 自测题

1. **问**：为什么 `setCount(count + 1)` 连写三次只加 1？
   **答**：`count` 是本次渲染的快照常量，三次调用传入的都是同一个值。React 批处理后只应用最后一次。改用 `setCount(c => c + 1)` 才会依次基于最新值累加。

2. **问**：`useEffect` 的清理函数何时执行？
   **答**：组件卸载时，以及**每次依赖变化导致 effect 重新执行之前**。React 会先跑上一次的清理，再执行新的 effect。

3. **问**：`useState` 的惰性初始化解决什么问题？
   **答**：`useState(expensiveCalc())` 每次渲染都会调用一次昂贵函数（虽然结果被丢弃）；写成 `useState(() => expensiveCalc())` 后，该函数只在首次渲染执行。

4. **问**：哪些场景**不需要** useEffect？
   **答**：由 props/state 派生的数据（渲染期直接算或 `useMemo`）、用户事件引发的逻辑（写在事件处理函数里）、以及仅用于重置状态的场景（可用 `key` 强制重建组件）。

## 核心知识点

### 一、Hooks 两条铁律

1. **只在最顶层调用**：不能放在条件、循环、嵌套函数、`try/catch` 中。React 靠**调用顺序**把每次渲染的 Hook 与其内部状态槽位对应起来，顺序一变，状态就串位。
2. **只在 React 函数中调用**：函数组件或另一个自定义 Hook 里，不能在普通函数、类组件、事件回调中调用。

```jsx
// ❌ 条件调用：条件变化时后续所有 Hook 全部错位
if (isLogin) {
  const [name, setName] = useState('');
}

// ✅ 先无条件调用，再在内部处理条件
const [name, setName] = useState('');
if (isLogin) { /* 使用 name */ }
```

用 `eslint-plugin-react-hooks` 的 `rules-of-hooks` 规则自动拦截这类错误。

### 二、自定义 Hook

自定义 Hook 就是**名字以 `use` 开头、内部调用了其他 Hook 的普通函数**。它复用的是**有状态逻辑**，不是状态本身——两个组件各自调用同一个 Hook，状态完全独立。

```ts
// useDebounce.ts —— 值防抖
import { useState, useEffect } from 'react';

export function useDebounce<T>(value: T, delay = 300): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer); // 值变化时取消上一个定时器
  }, [value, delay]);

  return debounced;
}
```

```ts
// useLocalStorage.ts —— 与 localStorage 同步的状态
import { useState, useCallback } from 'react';

export function useLocalStorage<T>(key: string, initial: T) {
  const [value, setValue] = useState<T>(() => {
    try {
      const raw = localStorage.getItem(key);
      return raw ? (JSON.parse(raw) as T) : initial;
    } catch {
      return initial;
    }
  });

  const update = useCallback(
    (next: T | ((prev: T) => T)) => {
      setValue((prev) => {
        const value = typeof next === 'function' ? (next as (p: T) => T)(prev) : next;
        localStorage.setItem(key, JSON.stringify(value));
        return value;
      });
    },
    [key],
  );

  return [value, update] as const; // as const 让返回值成为元组类型
}
```

### 三、订阅外部数据源：useSyncExternalStore

```ts
import { useSyncExternalStore } from 'react';

function subscribe(callback: () => void) {
  window.addEventListener('online', callback);
  window.addEventListener('offline', callback);
  return () => {
    window.removeEventListener('online', callback);
    window.removeEventListener('offline', callback);
  };
}

export function useOnlineStatus(): boolean {
  return useSyncExternalStore(
    subscribe,
    () => navigator.onLine,   // 客户端快照
    () => true,               // 服务端渲染快照
  );
}
```

这是订阅浏览器 API 或外部状态库的**官方推荐方式**，能避免并发渲染下的撕裂（tearing）问题。

### 四、组合使用

```tsx
function SearchPage() {
  const [keyword, setKeyword] = useState('');
  const debouncedKeyword = useDebounce(keyword, 400);
  const [history, setHistory] = useLocalStorage<string[]>('search-history', []);
  const online = useOnlineStatus();

  useEffect(() => {
    if (!debouncedKeyword) return;
    setHistory((prev) => [debouncedKeyword, ...prev].slice(0, 10));
  }, [debouncedKeyword, setHistory]);

  return (
    <>
      {!online && <p role="alert">当前离线</p>}
      <input value={keyword} onChange={(e) => setKeyword(e.target.value)} />
    </>
  );
}
```

### 实践任务

1. 实现 `usePrevious<T>(value)` 返回上一次渲染的值（提示：用 `useRef` + `useEffect`）。
2. 实现 `useToggle(initial)` 返回 `[state, toggle, setState]`。
3. 把项目里重复出现的「请求 + loading + error」逻辑抽成 `useRequest`。

### 🛑 易错点

1. **自定义 Hook 不以 `use` 开头**：ESLint 无法识别它是 Hook，规则检查全部失效，且团队成员会误以为可以在条件语句里调用。命名前缀是**约定也是工具依赖**。
2. **以为自定义 Hook 能共享状态**：每次调用都会创建**独立**的状态实例。真正要跨组件共享状态，需要 Context、外部 store 或状态管理库。
3. **返回数组却没标注元组类型**：TS 会把 `return [value, setValue]` 推断成联合类型数组，调用方解构后类型错乱。加 `as const` 或显式标注返回类型即可。
4. **在自定义 Hook 里用不稳定的返回函数**：每次渲染返回新函数引用，会让消费方的 `useEffect` 依赖不断变化引发死循环。返回的函数应用 `useCallback` 包裹。

### ✅ 自测题

1. **问**：为什么 Hooks 不能写在条件语句里？
   **答**：React 内部用**链表按调用顺序**存储每个 Hook 的状态。条件调用会让不同渲染的 Hook 数量或顺序不一致，导致状态错位读取到别的 Hook 的值。

2. **问**：自定义 Hook 复用的是什么？
   **答**：复用的是**有状态的逻辑**（如订阅、防抖、请求流程），而不是状态数据本身。每个调用点都拥有一份完全独立的 state 与 effect。

3. **问**：`useSyncExternalStore` 解决了什么问题？
   **答**：在并发渲染下，直接用 `useState + useEffect` 订阅外部数据源可能出现「同一次渲染中不同组件读到不同版本数据」的撕裂问题。该 Hook 保证快照读取一致，并原生支持 SSR。

4. **问**：如何让自定义 Hook 返回值获得元组类型？
   **答**：在 `return` 时加 `as const`（如 `return [value, setValue] as const`），或显式声明返回类型为 `[T, (v: T) => void]`。

## 核心知识点

### 一、状态放在哪里

决策顺序：**局部 state → 状态提升到最近公共父级 → Context → 外部状态库**。

不要一上来就上全局 store，绝大多数状态只属于某个子树。

### 二、useReducer：管理复杂状态转移

```tsx
import { useReducer } from 'react';

type State = { count: number; step: number };
type Action =
  | { type: 'inc' }
  | { type: 'dec' }
  | { type: 'setStep'; payload: number }
  | { type: 'reset' };

const initial: State = { count: 0, step: 1 };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'inc': return { ...state, count: state.count + state.step };
    case 'dec': return { ...state, count: state.count - state.step };
    case 'setStep': return { ...state, step: action.payload };
    case 'reset': return initial;
    default: return state;
  }
}

function Counter() {
  const [state, dispatch] = useReducer(reducer, initial);
  return (
    <>
      <p>{state.count}</p>
      <button onClick={() => dispatch({ type: 'inc' })}>+{state.step}</button>
      <button onClick={() => dispatch({ type: 'reset' })}>重置</button>
    </>
  );
}
```

当多个 state 需要一起变化、或更新逻辑分支复杂时，`useReducer` 比多个 `useState` 更容易测试与追踪。

### 三、Context：跨层级传值

Context 解决的是 **prop drilling（逐层透传）**，它不是状态管理器，本身不做性能优化。

```tsx
import { createContext, useContext, useMemo, useState } from 'react';

type Theme = 'light' | 'dark';
type ThemeCtx = { theme: Theme; toggle: () => void };

const ThemeContext = createContext<ThemeCtx | null>(null);

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setTheme] = useState<Theme>('light');

  // 关键：用 useMemo 稳定 value 引用，否则每次渲染都会通知所有消费者
  const value = useMemo<ThemeCtx>(
    () => ({ theme, toggle: () => setTheme((t) => (t === 'light' ? 'dark' : 'light')) }),
    [theme],
  );

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

// 自定义 Hook 封装：集中处理「未包裹 Provider」的错误
export function useTheme(): ThemeCtx {
  const ctx = useContext(ThemeContext);
  if (!ctx) throw new Error('useTheme 必须在 ThemeProvider 内使用');
  return ctx;
}
```

React 19 起可以直接把 `<ThemeContext>` 当作 Provider 使用（省略 `.Provider`），旧写法仍然有效。

### 四、Context 的性能陷阱与拆分

**只要 Provider 的 `value` 引用变化，所有 `useContext` 的组件都会重渲染**，与是否用到变化的那部分无关。

```tsx
// 优化：把「不常变的 dispatch」与「常变的 state」拆成两个 Context
const StateContext = createContext<State | null>(null);
const DispatchContext = createContext<React.Dispatch<Action> | null>(null);

function Provider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(reducer, initial);
  return (
    <StateContext.Provider value={state}>
      {/* dispatch 引用永远稳定，只消费它的组件不会因 state 变化而重渲染 */}
      <DispatchContext.Provider value={dispatch}>{children}</DispatchContext.Provider>
    </StateContext.Provider>
  );
}
```

需要细粒度订阅时，改用 Zustand、Jotai、Redux Toolkit 这类外部 store，它们基于 `useSyncExternalStore` 实现按选择器订阅。

### 实践任务

1. 把一个三层透传的 props 改造成 Context，再用自定义 Hook 封装消费入口。
2. 故意不加 `useMemo`，用 React DevTools Profiler 观察全量重渲染，再加上对比。
3. 用 `useReducer` 重写一个含 5 个 `useState` 的表单，体会状态收敛。

### 🛑 易错点

1. **Provider 的 value 直接写对象字面量**：`value={{ user, setUser }}` 每次渲染都是新引用，等于让所有消费者无条件重渲染。必须 `useMemo`。
2. **把所有状态塞进一个全局 Context**：任何一个字段变化都会波及整棵树。应按「变化频率」和「关注领域」拆分多个 Context。
3. **`createContext()` 不给默认值就直接用**：默认值为 `undefined` 时，忘记包 Provider 会得到 `undefined` 并在运行时崩溃。用 `null` 初始化 + 自定义 Hook 抛出明确错误，问题定位更快。
4. **在 Context 里存放高频变化的值（如鼠标坐标、输入框内容）**：会造成整棵子树每帧重渲染。这类状态应保持局部，或使用支持选择器订阅的外部 store。

### ✅ 自测题

1. **问**：Context 能替代 Redux 吗？
   **答**：不能完全替代。Context 只解决「跨层级传递」，缺少选择器订阅、中间件、时间旅行调试与细粒度更新。适合主题、语言、登录用户这类低频全局值；高频复杂状态应使用专门的状态库。

2. **问**：为什么 Provider 的 value 要用 useMemo 包裹？
   **答**：Context 通过 `Object.is` 比较 value。对象字面量每次渲染都是新引用，会导致全部消费者重渲染。`useMemo` 让引用只在真正的依赖变化时更新。

3. **问**：`useReducer` 相比 `useState` 的优势？
   **答**：把状态转移逻辑集中到纯函数 reducer 中，便于单元测试与追踪；多个字段联动更新时只需一次 dispatch；`dispatch` 引用天然稳定，方便向下传递而不破坏 memo。

4. **问**：如何减少 Context 引起的无效重渲染？
   **答**：拆分 Context（state 与 dispatch 分离、按领域分离）、value 用 `useMemo` 稳定、消费组件用 `React.memo` 包裹，或改用支持选择器的外部状态库。

## 核心知识点

### 一、渲染流程：Render → Reconcile → Commit

1. **触发**：初次挂载或 state/props 变化。
2. **Render 阶段**：调用组件函数得到新的 Element 树（**纯计算，可被打断**）。
3. **Reconciliation（协调）**：新旧树 diff。React 的启发式算法基于两条假设——**不同类型的元素产生不同的树**（直接卸载重建）；**开发者用 key 标记稳定元素**。
4. **Commit 阶段**：把差异一次性写入 DOM（同步，不可打断），随后执行 layout effect 与 passive effect。

**重要认知**：父组件重渲染时，其所有子组件默认都会重新执行 render 函数——但只有 diff 出差异的部分才会真正操作 DOM。所以「重渲染」不等于「重排 DOM」，不必对每个组件都做 memo。

### 二、key 的正确用法

```jsx
// ❌ 索引作 key：插入/删除/排序时状态错位
{items.map((item, i) => <Row key={i} item={item} />)}

// ✅ 稳定唯一 id
{items.map((item) => <Row key={item.id} item={item} />)}

// key 的另一个用途：强制重建组件以重置内部状态
<UserForm key={userId} userId={userId} />
```

### 三、memo / useMemo / useCallback

```tsx
import { memo, useMemo, useCallback, useState } from 'react';

// memo：props 浅比较相同则跳过重渲染
const ExpensiveList = memo(function ExpensiveList({
  items,
  onSelect,
}: {
  items: Item[];
  onSelect: (id: string) => void;
}) {
  return (
    <ul>
      {items.map((it) => (
        <li key={it.id} onClick={() => onSelect(it.id)}>{it.name}</li>
      ))}
    </ul>
  );
});

function Page({ raw }: { raw: Item[] }) {
  const [keyword, setKeyword] = useState('');
  const [selected, setSelected] = useState<string | null>(null);

  // 缓存计算结果：只有 raw / keyword 变化才重算
  const items = useMemo(
    () => raw.filter((i) => i.name.includes(keyword)),
    [raw, keyword],
  );

  // 缓存函数引用：否则每次渲染都是新函数，memo 失效
  const onSelect = useCallback((id: string) => setSelected(id), []);

  return (
    <>
      <input value={keyword} onChange={(e) => setKeyword(e.target.value)} />
      <ExpensiveList items={items} onSelect={onSelect} />
      <p>已选：{selected}</p>
    </>
  );
}
```

三者必须**配套使用**：给 memo 组件传了未缓存的对象或函数，memo 等于白加。

### 四、更有效的结构性优化

```jsx
// 1. 状态下移：让频繁变化的 state 只影响最小子树
function Page() {
  return (
    <>
      <ExpensiveTree />   {/* 不再因输入框变化而重渲染 */}
      <SearchInput />     {/* keyword 只存在于这里 */}
    </>
  );
}

// 2. children 作为 props：children 元素在父级创建，父组件重渲染时引用不变
function Wrapper({ children }) {
  const [n, setN] = useState(0);
  return <div onClick={() => setN(n + 1)}>{children}</div>;
}
```

### 五、并发特性

```tsx
import { useState, useTransition, useDeferredValue } from 'react';

function Search() {
  const [query, setQuery] = useState('');
  const [isPending, startTransition] = useTransition();
  const deferredQuery = useDeferredValue(query); // 让重列表用“滞后”的值渲染

  return (
    <>
      <input
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);                       // 紧急更新：输入框立刻响应
          startTransition(() => refreshResults(e.target.value)); // 非紧急：可被打断
        }}
      />
      {isPending && <span>搜索中…</span>}
      <ResultList query={deferredQuery} />
    </>
  );
}
```

### 实践任务

1. 用 React DevTools Profiler 录制交互，找出渲染耗时最长的组件。
2. 给一个万行表格加 memo + useCallback，对比 Profiler 数据。
3. 用 `useDeferredValue` 优化搜索联想，体验输入不卡顿。

### 🛑 易错点

1. **无脑给所有组件套 memo**：浅比较本身有成本，且缓存要占内存。只对「渲染开销大 + props 稳定」的组件使用。渲染很轻的组件加 memo 往往是负优化。
2. **`useCallback`/`useMemo` 的依赖写错**：依赖漏写会捕获过期闭包（点击时拿到旧 state），依赖过多则缓存永远失效。交给 `react-hooks/exhaustive-deps` 规则把关。
3. **把 `useMemo` 当作副作用容器**：`useMemo(() => { fetchData() }, [])` 是错误用法，它必须是**纯计算**且可能被 React 丢弃重算。副作用请用 `useEffect`。
4. **用索引当 key 后出现「输入内容跑错行」**：列表顺序变化时 React 按 key 复用 DOM 与组件状态，索引 key 导致状态与数据错配。务必使用稳定 id。

### ✅ 自测题

1. **问**：React 的 diff 算法基于哪两个假设？
   **答**：① 不同类型的元素会产生完全不同的树，因此类型变化时直接卸载旧子树、重建新子树；② 开发者可以通过 `key` 标示哪些子元素在多次渲染中保持稳定，从而实现同层节点的高效复用。

2. **问**：`useMemo` 和 `useCallback` 的关系？
   **答**：`useCallback(fn, deps)` 等价于 `useMemo(() => fn, deps)`。前者缓存函数引用，后者缓存计算结果，都是为了保持引用稳定或避免重复计算。

3. **问**：为什么「状态下移」常常比 memo 更有效？
   **答**：memo 只是在渲染发生后跳过子树，而状态下移从根本上缩小了会被重渲染的范围，不需要额外的比较成本，也不依赖 props 引用稳定性。

4. **问**：`useTransition` 与 `useDeferredValue` 有什么区别？
   **答**：`useTransition` 用于把**你能控制的更新**标记为非紧急，并提供 `isPending` 状态；`useDeferredValue` 用于**你只能拿到值**（如来自 props）的场景，让消费该值的重渲染滞后进行。

## 核心知识点

### 一、React Router v6.4+ 数据路由

```tsx
import {
  createBrowserRouter,
  RouterProvider,
  Outlet,
  NavLink,
  useLoaderData,
  useNavigation,
  useRouteError,
  redirect,
} from 'react-router-dom';

function Layout() {
  const navigation = useNavigation();
  return (
    <>
      <nav>
        <NavLink to="/" end className={({ isActive }) => (isActive ? 'active' : '')}>
          首页
        </NavLink>
        <NavLink to="/users">用户</NavLink>
      </nav>
      {navigation.state === 'loading' && <div className="bar">加载中…</div>}
      <Outlet />  {/* 子路由渲染出口 */}
    </>
  );
}

function ErrorPage() {
  const error = useRouteError() as { statusText?: string; message?: string };
  return <p role="alert">出错了：{error.statusText ?? error.message}</p>;
}

const router = createBrowserRouter([
  {
    path: '/',
    element: <Layout />,
    errorElement: <ErrorPage />,
    children: [
      { index: true, element: <Home /> },
      {
        path: 'users/:id',
        // loader：进入路由前并行取数，消灭「渲染后才请求」的瀑布
        loader: async ({ params, request }) => {
          const res = await fetch(`/api/users/${params.id}`, { signal: request.signal });
          if (res.status === 404) throw new Response('Not Found', { status: 404 });
          return res.json();
        },
        element: <UserDetail />,
      },
      {
        path: 'login',
        action: async ({ request }) => {
          const form = await request.formData();
          await login(form.get('email'));
          return redirect('/');   // action 里做跳转
        },
        element: <Login />,
      },
      { path: '*', element: <NotFound /> },
    ],
  },
]);

export default function App() {
  return <RouterProvider router={router} />;
}

function UserDetail() {
  const user = useLoaderData() as { id: string; name: string };
  return <h1>{user.name}</h1>;
}
```

`useFetcher` 用于「不触发导航」的数据交互（如点赞、行内保存）：

