function LikeButton({ id }: { id: string }) {
  const fetcher = useFetcher();
  return (
    <fetcher.Form method="post" action={`/posts/${id}/like`}>
      <button disabled={fetcher.state !== 'idle'}>
        {fetcher.state === 'submitting' ? '提交中' : '点赞'}
      </button>
    </fetcher.Form>
  );
}
```

